#include "physics/CCPhysicsSpatialIndex.h"
#if CC_USE_PHYSICS

#include <algorithm>
#include <cmath>
#include <set>
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    // Accumulator used by cpBodyEachShape() to union the bounding boxes of
    // all shapes attached to a body.
    struct BBAccumulator
    {
        cpBB bb;
        bool hasShape;
    };

    void accumulateShapeBB(cpBody* /*body*/, cpShape* shape, void* data)
    {
        BBAccumulator* acc = static_cast<BBAccumulator*>(data);
        cpBB bb = cpShapeCacheBB(shape);
        if (!acc->hasShape)
        {
            acc->bb = bb;
            acc->hasShape = true;
        }
        else
        {
            acc->bb.l = std::min(acc->bb.l, bb.l);
            acc->bb.b = std::min(acc->bb.b, bb.b);
            acc->bb.r = std::max(acc->bb.r, bb.r);
            acc->bb.t = std::max(acc->bb.t, bb.t);
        }
    }

    // Slab-method segment vs AABB intersection test.
    bool segmentIntersectsRect(const Vec2& a, const Vec2& b, const Rect& rect)
    {
        float tmin = 0.0f;
        float tmax = 1.0f;
        Vec2 d = b - a;

        const float mins[2] = { rect.getMinX(), rect.getMinY() };
        const float maxs[2] = { rect.getMaxX(), rect.getMaxY() };
        const float origin[2] = { a.x, a.y };
        const float dir[2] = { d.x, d.y };

        for (int i = 0; i < 2; ++i)
        {
            if (std::fabs(dir[i]) < 1e-8f)
            {
                // Segment is parallel to this slab: origin must be inside it.
                if (origin[i] < mins[i] || origin[i] > maxs[i])
                    return false;
            }
            else
            {
                float invD = 1.0f / dir[i];
                float t1 = (mins[i] - origin[i]) * invD;
                float t2 = (maxs[i] - origin[i]) * invD;
                if (t1 > t2)
                    std::swap(t1, t2);
                tmin = std::max(tmin, t1);
                tmax = std::min(tmax, t2);
                if (tmin > tmax)
                    return false;
            }
        }
        return true;
    }

    // Distance from a point to an AABB (0 when the point is inside).
    float pointRectDistanceSq(const Vec2& p, const Rect& rect)
    {
        float cx = std::max(rect.getMinX(), std::min(p.x, rect.getMaxX()));
        float cy = std::max(rect.getMinY(), std::min(p.y, rect.getMaxY()));
        float dx = p.x - cx;
        float dy = p.y - cy;
        return dx * dx + dy * dy;
    }
}

PhysicsSpatialIndex::PhysicsSpatialIndex()
: _cellSize(64.0f)
, _worldBounds(Rect::ZERO)
, _gridWidth(0)
, _gridHeight(0)
, _initialized(false)
{
}

PhysicsSpatialIndex::~PhysicsSpatialIndex()
{
}

bool PhysicsSpatialIndex::init(float cellSize, const Rect& worldBounds)
{
    if (cellSize <= 0.0f)
        return false;

    _cellSize = cellSize;
    _worldBounds = worldBounds;
    _gridWidth = std::max(1, (int)std::ceil(worldBounds.size.width / cellSize));
    _gridHeight = std::max(1, (int)std::ceil(worldBounds.size.height / cellSize));

    _cells.clear();
    _cells.resize((size_t)_gridWidth * (size_t)_gridHeight);
    _trackedBodies.clear();
    _initialized = true;
    return true;
}

void PhysicsSpatialIndex::clear()
{
    for (auto& cell : _cells)
    {
        cell.clear();
    }
    _trackedBodies.clear();
}

void PhysicsSpatialIndex::insertBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr)
        return;

    if (_trackedBodies.find(body) != _trackedBodies.end())
    {
        // Already tracked: reinsert so the grid reflects the current bounds.
        removeBody(body);
    }

    Rect bounds = getBodyBounds(body);
    int minCX, minCY, maxCX, maxCY;
    getCellCoords(Vec2(bounds.getMinX(), bounds.getMinY()), minCX, minCY);
    getCellCoords(Vec2(bounds.getMaxX(), bounds.getMaxY()), maxCX, maxCY);

    for (int cy = minCY; cy <= maxCY; ++cy)
    {
        for (int cx = minCX; cx <= maxCX; ++cx)
        {
            _cells[cellIndex(cx, cy)].push_back(body);
        }
    }
    _trackedBodies.insert(body);
}

void PhysicsSpatialIndex::removeBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr)
        return;

    if (_trackedBodies.erase(body) == 0)
        return;

    // The body may have moved since it was inserted, so scan every cell
    // instead of relying on its current bounds.
    for (auto& cell : _cells)
    {
        cell.erase(std::remove(cell.begin(), cell.end(), body), cell.end());
    }
}

void PhysicsSpatialIndex::updateBody(PhysicsBody* body)
{
    if (!_initialized || body == nullptr)
        return;

    removeBody(body);
    insertBody(body);
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::queryRect(const Rect& rect) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || _cells.empty())
        return result;

    int minCX, minCY, maxCX, maxCY;
    getCellCoords(Vec2(rect.getMinX(), rect.getMinY()), minCX, minCY);
    getCellCoords(Vec2(rect.getMaxX(), rect.getMaxY()), maxCX, maxCY);

    std::unordered_set<PhysicsBody*> seen;
    for (int cy = minCY; cy <= maxCY; ++cy)
    {
        for (int cx = minCX; cx <= maxCX; ++cx)
        {
            for (auto* body : _cells[cellIndex(cx, cy)])
            {
                if (seen.insert(body).second && getBodyBounds(body).intersectsRect(rect))
                {
                    result.push_back(body);
                }
            }
        }
    }
    return result;
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::queryCircle(const Vec2& center, float radius) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || _cells.empty() || radius < 0.0f)
        return result;

    Rect boundsRect(center.x - radius, center.y - radius, radius * 2.0f, radius * 2.0f);
    int minCX, minCY, maxCX, maxCY;
    getCellCoords(Vec2(boundsRect.getMinX(), boundsRect.getMinY()), minCX, minCY);
    getCellCoords(Vec2(boundsRect.getMaxX(), boundsRect.getMaxY()), maxCX, maxCY);

    const float radiusSq = radius * radius;
    std::unordered_set<PhysicsBody*> seen;
    for (int cy = minCY; cy <= maxCY; ++cy)
    {
        for (int cx = minCX; cx <= maxCX; ++cx)
        {
            for (auto* body : _cells[cellIndex(cx, cy)])
            {
                if (seen.insert(body).second
                    && pointRectDistanceSq(center, getBodyBounds(body)) <= radiusSq)
                {
                    result.push_back(body);
                }
            }
        }
    }
    return result;
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::querySegment(const Vec2& start, const Vec2& end) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || _cells.empty())
        return result;

    float minX = std::min(start.x, end.x);
    float minY = std::min(start.y, end.y);
    float maxX = std::max(start.x, end.x);
    float maxY = std::max(start.y, end.y);

    int minCX, minCY, maxCX, maxCY;
    getCellCoords(Vec2(minX, minY), minCX, minCY);
    getCellCoords(Vec2(maxX, maxY), maxCX, maxCY);

    std::unordered_set<PhysicsBody*> seen;
    for (int cy = minCY; cy <= maxCY; ++cy)
    {
        for (int cx = minCX; cx <= maxCX; ++cx)
        {
            for (auto* body : _cells[cellIndex(cx, cy)])
            {
                if (seen.insert(body).second
                    && segmentIntersectsRect(start, end, getBodyBounds(body)))
                {
                    result.push_back(body);
                }
            }
        }
    }
    return result;
}

std::vector<BroadPhasePair> PhysicsSpatialIndex::findPotentialPairs() const
{
    std::vector<BroadPhasePair> pairs;
    if (!_initialized)
        return pairs;

    std::set<std::pair<PhysicsBody*, PhysicsBody*>> emitted;
    for (const auto& cell : _cells)
    {
        const size_t count = cell.size();
        for (size_t i = 0; i < count; ++i)
        {
            for (size_t j = i + 1; j < count; ++j)
            {
                PhysicsBody* bodyA = cell[i];
                PhysicsBody* bodyB = cell[j];
                // Canonical ordering so a pair is only emitted once even when
                // the two bodies share several cells.
                if (bodyB < bodyA)
                    std::swap(bodyA, bodyB);

                if (!emitted.insert(std::make_pair(bodyA, bodyB)).second)
                    continue;

                if (getBodyBounds(bodyA).intersectsRect(getBodyBounds(bodyB)))
                {
                    BroadPhasePair pair;
                    pair.bodyA = bodyA;
                    pair.bodyB = bodyB;
                    pairs.push_back(pair);
                }
            }
        }
    }
    return pairs;
}

int PhysicsSpatialIndex::getCellCount() const
{
    return (int)_cells.size();
}

int PhysicsSpatialIndex::getBodyCount() const
{
    return (int)_trackedBodies.size();
}

float PhysicsSpatialIndex::getCellSize() const
{
    return _cellSize;
}

void PhysicsSpatialIndex::rebuild()
{
    if (!_initialized)
        return;

    std::vector<PhysicsBody*> bodies(_trackedBodies.begin(), _trackedBodies.end());

    _gridWidth = std::max(1, (int)std::ceil(_worldBounds.size.width / _cellSize));
    _gridHeight = std::max(1, (int)std::ceil(_worldBounds.size.height / _cellSize));
    _cells.clear();
    _cells.resize((size_t)_gridWidth * (size_t)_gridHeight);
    _trackedBodies.clear();

    for (auto* body : bodies)
    {
        insertBody(body);
    }
}

void PhysicsSpatialIndex::setCellSize(float size)
{
    if (size <= 0.0f || size == _cellSize)
        return;

    _cellSize = size;
    if (_initialized)
        rebuild();
}

void PhysicsSpatialIndex::setWorldBounds(const Rect& bounds)
{
    _worldBounds = bounds;
    if (_initialized)
        rebuild();
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::getNearestBodies(const Vec2& point, int maxCount) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || maxCount <= 0)
        return result;

    result.assign(_trackedBodies.begin(), _trackedBodies.end());
    std::sort(result.begin(), result.end(),
        [this, &point](PhysicsBody* a, PhysicsBody* b)
        {
            return pointRectDistanceSq(point, getBodyBounds(a))
                 < pointRectDistanceSq(point, getBodyBounds(b));
        });

    if ((int)result.size() > maxCount)
        result.resize((size_t)maxCount);
    return result;
}

std::vector<PhysicsBody*> PhysicsSpatialIndex::getBodiesInFrustum(const Vec2& origin, const Vec2& direction, float angle, float distance) const
{
    std::vector<PhysicsBody*> result;
    if (!_initialized || distance < 0.0f || angle <= 0.0f)
        return result;

    Vec2 dir = direction;
    if (dir.lengthSquared() < 1e-12f)
        return result;
    dir.normalize();

    // `angle` is the full cone aperture in degrees.
    const float halfAngleRad = angle * 0.5f * (float)M_PI / 180.0f;
    const float cosHalfAngle = std::cos(halfAngleRad);

    for (auto* body : _trackedBodies)
    {
        Rect bounds = getBodyBounds(body);
        Vec2 toBody(bounds.getMidX() - origin.x, bounds.getMidY() - origin.y);

        float dist = toBody.getLength();
        if (dist > distance)
            continue;

        // A body at (or almost at) the origin is always inside the cone.
        if (dist > 1e-6f && Vec2::dot(toBody / dist, dir) < cosHalfAngle)
            continue;

        result.push_back(body);
    }
    return result;
}

int PhysicsSpatialIndex::cellIndex(int x, int y) const
{
    return y * _gridWidth + x;
}

void PhysicsSpatialIndex::getCellCoords(const Vec2& point, int& outX, int& outY) const
{
    int x = (int)std::floor((point.x - _worldBounds.origin.x) / _cellSize);
    int y = (int)std::floor((point.y - _worldBounds.origin.y) / _cellSize);
    outX = std::max(0, std::min(x, _gridWidth - 1));
    outY = std::max(0, std::min(y, _gridHeight - 1));
}

Rect PhysicsSpatialIndex::getBodyBounds(PhysicsBody* body) const
{
    if (body == nullptr)
        return Rect::ZERO;

    cpBody* cpBody = body->getCPBody();
    if (cpBody != nullptr)
    {
        BBAccumulator acc;
        acc.hasShape = false;
        acc.bb = cpBBNew(0, 0, 0, 0);
        cpBodyEachShape(cpBody, accumulateShapeBB, &acc);
        if (acc.hasShape)
            return PhysicsHelper::cpbb2rect(acc.bb);
    }

    // No chipmunk body or no shapes: fall back to a degenerate rect at the
    // body's position so point-like bodies still live in exactly one cell.
    Vec2 pos = body->getPosition();
    return Rect(pos.x, pos.y, 0.0f, 0.0f);
}

